const test = require('node:test');
const assert = require('node:assert/strict');
const vm = require('node:vm');
const fs = require('node:fs');
function setup() {
 const elements=new Map();const get=id=>{if(!elements.has(id))elements.set(id,{value:'',checked:false,textContent:'',hidden:true,append(){},replaceChildren(){},scrollIntoView(){}});return elements.get(id);};
 const calls=[];const store=new Map();const context={document:{getElementById:get,createElement:()=>({}),head:{append(){}}},localStorage:{getItem:k=>store.get(k),setItem:(k,v)=>store.set(k,v)},navigator:{},setTimeout,clearTimeout,URL,console,puter:{auth:{isSignedIn:()=>true},ai:{chat:async(messages,options)=>{calls.push({messages,options});return {message:{content:'<script>not executable</script> Specific review'}};}}}};context.window=context;vm.createContext(context);vm.runInContext(fs.readFileSync('app/src/main/assets/tiktok_reviewer.js','utf8'),context);return {get,calls,context,store};
}
test('requires evidence and explicit content-sharing consent',async()=>{const s=setup();await s.get('review').onclick();assert.equal(s.calls.length,0);s.get('script').value='My draft';await s.get('review').onclick();assert.equal(s.calls.length,0);assert.match(s.get('error').textContent,/consent/);});
test('text review uses existing model, factual limits and local history',async()=>{const s=setup();s.get('script').value='My draft';s.get('consent').checked=true;await s.get('review').onclick();assert.equal(s.calls.length,1);assert.equal(s.calls[0].options.model,'qwen/qwen3.6-27b');assert.match(s.calls[0].messages[0].content,/Do not claim to hear audio/);assert.match(s.get('report').textContent,/<script>/);assert.equal(JSON.parse(s.store.get('tiktok-reviews-v1')).length,1);s.get('clear').onclick();assert.equal(JSON.parse(s.store.get('tiktok-reviews-v1')).length,0);});
test('video review sends timestamped stills to vision model',async()=>{const s=setup();vm.runInContext("frames=[{time:1.5,image:'data:image/jpeg;base64,abc'}]",s.context);s.get('consent').checked=true;await s.get('review').onclick();assert.equal(s.calls[0].options.model,'gpt-4.1-mini');assert.equal(s.calls[0].messages[1].content[2].type,'image_url');assert.match(s.calls[0].messages[1].content[1].text,/1.5/);});
test('provider failure leaves inputs available and does not save a false review',async()=>{const s=setup();s.context.puter.ai.chat=async()=>{throw new Error('Quota exceeded');};s.get('script').value='Keep this';s.get('consent').checked=true;await s.get('review').onclick();assert.match(s.get('error').textContent,/Quota exceeded/);assert.equal(s.get('script').value,'Keep this');assert.equal(s.get('review').disabled,false);assert.equal(s.store.size,0);});
